from __future__ import annotations

import json

MANAGEMENT_UI_CSS = r'''
.v2-manage{grid-column:1/-1;border:1px solid var(--v2-border);border-radius:20px;padding:16px;background:linear-gradient(150deg,rgba(17,29,47,.95),rgba(6,15,27,.94));box-shadow:var(--v2-shadow);margin-top:10px}.v2-manage-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;flex-wrap:wrap}.v2-manage-head h3{margin:0;font-size:15px}.v2-manage-head p{margin:4px 0 0;color:var(--v2-muted);font-size:11px;max-width:760px}.v2-manage-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px;margin-top:13px}.v2-manage-grid label{font-size:9px;color:var(--v2-muted);text-transform:uppercase;letter-spacing:.05em}.v2-manage-grid input,.v2-manage-grid select,.v2-manage-grid textarea{margin-top:5px;text-transform:none;letter-spacing:normal}.v2-manage-grid textarea{min-height:80px;resize:vertical}.v2-manage-span2{grid-column:span 2}.v2-manage-span3{grid-column:1/-1}.v2-manage-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.v2-manage-preview{margin-top:12px;border:1px solid rgba(148,163,184,.12);border-radius:15px;padding:11px;background:rgba(4,11,21,.48);font-size:10px}.v2-manage-preview pre{white-space:pre-wrap;word-break:break-word;max-height:260px;overflow:auto;color:#c8d8ea;margin:8px 0 0}.v2-manage-confirm{margin-top:10px;display:none}.v2-manage-confirm.visible{display:block}.v2-manage-status{margin-top:9px;color:var(--v2-muted);font-size:10px}.v2-manage-status.ok{color:#bbf7d0}.v2-manage-status.warn{color:#fde68a}.v2-manage-danger{border-color:rgba(248,113,113,.35)!important}.v2-manage-lock{display:inline-flex;padding:7px 9px;border-radius:999px;border:1px solid rgba(148,163,184,.13);font-size:9px;color:var(--v2-muted)}.v2-manage-lock.active{color:#bbf7d0;border-color:rgba(52,211,153,.3)}@media(max-width:900px){.v2-manage-grid{grid-template-columns:1fr 1fr}.v2-manage-span3{grid-column:1/-1}}@media(max-width:620px){.v2-manage-grid{grid-template-columns:1fr}.v2-manage-span2,.v2-manage-span3{grid-column:auto}.v2-manage-actions .btn{flex:1}}
'''

MANAGEMENT_UI_JS = r'''
(()=>{
 const esc=v=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));
 const readFile=async file=>{const buf=await file.arrayBuffer();const digest=await crypto.subtle.digest('SHA-256',buf);const sha=[...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,'0')).join('');const bytes=new Uint8Array(buf);let binary='';const step=0x8000;for(let i=0;i<bytes.length;i+=step)binary+=String.fromCharCode(...bytes.subarray(i,i+step));return{content_base64:btoa(binary),sha256:sha,size_bytes:bytes.length,mime_type:file.type}};
 const install=async()=>{if(document.querySelector('[data-v2-management]'))return true;const section=document.getElementById('settings'),grid=section&&section.querySelector('.grid');if(!grid)return false;const card=document.createElement('article');card.className='v2-manage';card.dataset.v2Management='1';card.innerHTML=`<div class="v2-manage-head"><div><h3>Central de gerenciamento supervisionado</h3><p>Vídeos, playlists, itens, privacidade e thumbnails. Toda mudança passa por prévia, confirmação, Write Gateway e readback. Nada é aplicado ao selecionar uma opção.</p></div><span class="v2-manage-lock" data-v2-manage-lock>Write Gateway: consultando…</span></div><div class="v2-manage-grid"><label>Ação<select data-v2-manage-action><option value="video_privacy">Privacidade de vídeo</option><option value="playlist_create">Criar playlist</option><option value="playlist_update">Editar playlist</option><option value="playlist_item_add">Adicionar vídeo à playlist</option><option value="playlist_item_reorder">Reordenar item</option><option value="thumbnail_replace">Substituir thumbnail</option><option value="playlist_item_remove">Remover item da playlist</option><option value="playlist_delete">Excluir playlist</option><option value="video_delete">Excluir vídeo</option></select></label><label data-f="video_id">Video ID<input data-v2-video-id autocomplete="off"></label><label data-f="playlist_id">Playlist ID<input data-v2-playlist-id autocomplete="off"></label><label data-f="playlist_item_id">Playlist item ID<input data-v2-playlist-item-id autocomplete="off"></label><label data-f="privacy">Privacidade<select data-v2-privacy><option value="private">Privado</option><option value="unlisted">Não listado</option><option value="public">Público</option></select></label><label data-f="position">Posição<input data-v2-position type="number" min="0" value="0"></label><label class="v2-manage-span2" data-f="title">Título<input data-v2-title maxlength="150"></label><label class="v2-manage-span3" data-f="description">Descrição<textarea data-v2-description maxlength="5000"></textarea></label><label class="v2-manage-span2" data-f="thumbnail">Thumbnail JPEG/PNG até 2 MB<input data-v2-thumbnail type="file" accept="image/jpeg,image/png"></label></div><div class="v2-manage-actions"><button class="btn primary" type="button" data-v2-manage-preview>Gerar prévia segura</button><button class="btn" type="button" data-v2-manage-clear>Limpar</button></div><div class="v2-manage-preview"><b>Prévia / diff</b><pre data-v2-manage-diff>Nenhuma proposta criada.</pre><div class="v2-manage-confirm" data-v2-manage-confirm><label>Confirmação específica<input data-v2-manage-confirm-text autocomplete="off"></label><div class="v2-manage-actions"><button class="btn primary" type="button" data-v2-manage-apply>Confirmar e aplicar</button><button class="btn" type="button" data-v2-manage-rollback disabled>Desfazer alteração verificada</button></div></div></div><div class="v2-manage-status" data-v2-manage-status>Nenhuma escrita foi executada.</div>`;grid.append(card);
 const q=s=>card.querySelector(s),action=q('[data-v2-manage-action]'),status=q('[data-v2-manage-status]'),diff=q('[data-v2-manage-diff]'),confirmBox=q('[data-v2-manage-confirm]'),confirmInput=q('[data-v2-manage-confirm-text]'),apply=q('[data-v2-manage-apply]'),rollback=q('[data-v2-manage-rollback]'),lock=q('[data-v2-manage-lock]');let proposal=null,thumbnail=null;
 const schema={video_privacy:['video_id','privacy'],video_delete:['video_id'],playlist_create:['title','description','privacy'],playlist_update:['playlist_id','title','description','privacy'],playlist_delete:['playlist_id'],playlist_item_add:['playlist_id','video_id','position'],playlist_item_remove:['playlist_id','playlist_item_id'],playlist_item_reorder:['playlist_id','playlist_item_id','position'],thumbnail_replace:['video_id','thumbnail']};
 const paintFields=()=>{const show=new Set(schema[action.value]||[]);card.querySelectorAll('[data-f]').forEach(el=>el.style.display=show.has(el.dataset.f)?'block':'none');card.classList.toggle('v2-manage-danger',action.value.includes('delete')||action.value.includes('remove'));proposal=null;thumbnail=null;diff.textContent='Nenhuma proposta criada.';confirmBox.classList.remove('visible');rollback.disabled=true;status.className='v2-manage-status';status.textContent='Ação selecionada. Nada foi executado.'};
 const loadLock=async()=>{try{const r=await fetch('/api/v2/write-mode',{headers:{Accept:'application/json'}}),d=await r.json();lock.textContent='Write Gateway: '+(d.enabled?'ativo nesta sessão':'bloqueado');lock.classList.toggle('active',!!d.enabled);return !!d.enabled}catch{return false}};
 const payload=async()=>{const p={action:action.value,video_id:q('[data-v2-video-id]').value.trim(),playlist_id:q('[data-v2-playlist-id]').value.trim(),playlist_item_id:q('[data-v2-playlist-item-id]').value.trim(),privacy_status:q('[data-v2-privacy]').value,position:Number(q('[data-v2-position]').value||0),title:q('[data-v2-title]').value,description:q('[data-v2-description]').value};if(action.value==='thumbnail_replace'){const file=q('[data-v2-thumbnail]').files[0];if(!file)throw new Error('Selecione a thumbnail.');thumbnail=await readFile(file);p.mime_type=thumbnail.mime_type;p.size_bytes=thumbnail.size_bytes;p.sha256=thumbnail.sha256}return p};
 q('[data-v2-manage-preview]').addEventListener('click',async()=>{status.className='v2-manage-status';status.textContent='Gerando prévia somente leitura…';try{const p=await payload(),r=await fetch('/api/v2/manage/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)}),d=await r.json();if(!r.ok)throw new Error(d.detail||'Falha ao gerar prévia');proposal=d;diff.textContent=JSON.stringify({state:d.state,target_kind:d.target_kind,target_id:d.target_id,operation:d.operation,current:d.current,proposed:d.proposed,diff:d.diff,reversible:d.reversible},null,2);confirmBox.classList.add('visible');confirmInput.value='';confirmInput.placeholder=d.confirmation_phrase||'Confirme aplicando o botão abaixo';status.classList.add('warn');status.textContent=d.confirmation_phrase?`Para aplicar, digite exatamente: ${d.confirmation_phrase}`:'Prévia criada. Ainda não houve escrita no YouTube.';await loadLock()}catch(err){proposal=null;confirmBox.classList.remove('visible');status.classList.add('warn');status.textContent=esc(err.message||err)}});
 apply.addEventListener('click',async()=>{if(!proposal){status.textContent='Gere uma prévia primeiro.';return}if(!(await loadLock())){status.className='v2-manage-status warn';status.textContent='Write Gateway está bloqueado. Ative o gerenciamento nesta sessão antes de aplicar.';return}apply.disabled=true;status.textContent='Aplicando somente a proposta aprovada e verificando readback…';try{const body={confirmed:true,confirmation_text:confirmInput.value};if(proposal.target_kind==='thumbnail'){if(!thumbnail)throw new Error('Arquivo da thumbnail não está mais disponível nesta sessão. Gere a prévia novamente.');Object.assign(body,thumbnail)}const r=await fetch(`/api/v2/manage/apply/${encodeURIComponent(proposal.action_id)}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok)throw new Error(d.detail||'Falha ao aplicar');if(!d.readback_verified)throw new Error('A API não confirmou o estado final por readback.');status.className='v2-manage-status ok';status.textContent=`Alteração verificada no YouTube. Writes executados nesta ação: ${d.youtube_write_actions_executed}.`;rollback.disabled=!d.rollback_available;proposal={...proposal,target_id:d.target_id,state:d.state}}catch(err){status.className='v2-manage-status warn';status.textContent=esc(err.message||err)}finally{apply.disabled=false}});
 rollback.addEventListener('click',async()=>{if(!proposal)return;rollback.disabled=true;try{const r=await fetch(`/api/v2/manage/rollback/${encodeURIComponent(proposal.action_id)}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirmed:true})}),d=await r.json();if(!r.ok)throw new Error(d.detail||'Falha no rollback');status.className='v2-manage-status ok';status.textContent='Rollback solicitado e concluído pelo gateway seguro.'}catch(err){status.className='v2-manage-status warn';status.textContent=esc(err.message||err)}});
 q('[data-v2-manage-clear]').addEventListener('click',()=>{card.querySelectorAll('input:not([type=file]),textarea').forEach(el=>el.value='');q('[data-v2-thumbnail]').value='';paintFields()});action.addEventListener('change',paintFields);paintFields();loadLock();return true};
 if(!install()){const o=new MutationObserver(()=>{if(install())o.disconnect()});o.observe(document.documentElement,{childList:true,subtree:true});setTimeout(()=>o.disconnect(),10000)}
})();
'''


def management_ui_webengine_source() -> str:
    css_json = json.dumps(MANAGEMENT_UI_CSS, ensure_ascii=False)
    return (
        "(()=>{if(!document.querySelector('style[data-yca-v2-management-ui]')){"
        "const s=document.createElement('style');s.dataset.ycaV2ManagementUi='1';"
        f"s.textContent={css_json};(document.head||document.documentElement).appendChild(s);"
        "}})();\n" + MANAGEMENT_UI_JS
    )
